glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
out vec4 v_time;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  v_time = cc_time;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
in vec4 v_color;
in vec4 v_time;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform Constant {
  float flowSpeed;
  float flowWidth;
  float flowK;
  float flowCycle;
  float flowStrength;
  float lightSpeed;
  float opacity;
  float aspectRatio;
  vec4 flowColor;
};
void main () {
  vec4 o = vec4(1.0);
  vec4 o2 = vec4(1.0);
  float time = v_time.x * lightSpeed;
  float t1 = mod(v_time.x * lightSpeed , 1.);
  float cycleTime = mod(time, 1.0);
  float startTime  = 0.408;
  float visibleEnd = 0.72;
  const float PI   = 3.14159265;
  float entryMargin   = flowWidth * 3.0;
  float exitMargin    = flowWidth;
  float startB1       = -entryMargin;
  float visibleEndB1  = aspectRatio;
  float endB1         = 1.0 - flowK + exitMargin;
  float p = (visibleEndB1 - startB1) / (endB1 - startB1);
  float q = (2.0 / PI) * asin(p);
  float endTime = min(startTime + (visibleEnd - startTime) / q, 0.98);
  float b1 = 0.0;
  float dynamicWidth = flowWidth;
  float flowMask = 0.0;
  if (cycleTime >= startTime && cycleTime <= endTime) {
    float u            = (cycleTime - startTime) / (endTime - startTime);
    float easeT        = sin(0.5 * PI * u);
    dynamicWidth       = flowWidth * (1.0 + (1.0 - u) * 2.0);
    b1                 = mix(startB1, endB1, easeT);
    float flowLine = smoothstep(0.0, dynamicWidth,
        abs(v_uv0.y - (flowK * v_uv0.x + b1)));
    flowMask = 1.0 - flowLine;
  } else {
    flowMask = 0.0;
  }
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  o *= v_color;
  float effectStrength = flowMask * flowColor.a;
  o.rgb = mix(o.rgb, flowColor.rgb, effectStrength);
  o.rgb = mix(o.rgb, o.rgb * o.rgb, 0.3 * effectStrength);
  o.a = mix(o.a, 1.0, effectStrength * step(0.09, o.a));
  gl_FragColor = o.rgba;
}

